using System.IO;
using System.Windows.Media.Imaging;

namespace RadialConvert.UI;

/// <summary>The logo, embedded in the exe (generated by tools/LogoGen).</summary>
internal static class AppIcon
{
    static BitmapSource? _logo;

    public static System.Drawing.Icon TrayIcon()
    {
        using Stream stream = Open("RadialConvert.logo.ico");
        return new System.Drawing.Icon(stream, System.Windows.Forms.SystemInformation.SmallIconSize);
    }

    public static BitmapSource Logo()
    {
        if (_logo is null)
        {
            using Stream stream = Open("RadialConvert.logo-128.png");
            var frame = new PngBitmapDecoder(stream, BitmapCreateOptions.None, BitmapCacheOption.OnLoad).Frames[0];
            frame.Freeze();
            _logo = frame;
        }
        return _logo;
    }

    static Stream Open(string name) =>
        typeof(AppIcon).Assembly.GetManifestResourceStream(name)
        ?? throw new FileNotFoundException($"Embedded resource '{name}' is missing");
}
